using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public sealed class InternetPage:PlayerPage {
  readonly Label connection,ping,stability,problem,limitState;readonly TextBox host=new TextBox {Width=260,Text="1.1.1.1",BackColor=Theme.Surface,ForeColor=Theme.Text};readonly CheckBox limit=new CheckBox {Text="Ограничения фоновой отправки файлов",AutoSize=true,ThreeState=true};readonly NumericUpDown speed=new ThemedNumericUpDown {Minimum=1,Maximum=10000,Value=2,Width=100};readonly Button start,cancel;readonly TextBox executable=new TextBox {Width=360,ReadOnly=true,BackColor=Theme.Surface,ForeColor=Theme.Text};CancellationTokenSource cts;bool render;
  public InternetPage(PlayerContext context,Action<int,string> expert):base(context,"Интернет","Понятная диагностика и управление фоновыми загрузками без смены игровых маршрутов."){Name="internetPage";var card=new PlayerCard();card.Add(PlayerUi.Text("Состояние соединения",18,true));connection=PlayerUi.Text("Ещё не проверено");card.Add(connection);card.Add(PlayerUi.Text("Проверяется выбранный диагностический узел. Это не ping игрового сервера и не измерение его UDP-потерь.",10,false,Theme.Muted));card.Add(host);start=PlayerUi.Button("Проверить сеть","simpleNetworkStart",true);cancel=PlayerUi.Button("Завершить проверку","simpleNetworkCancel");cancel.Enabled=false;card.Add(start);card.Add(cancel);PlayerUi.Action(start,Probe,context);cancel.Click+=delegate{if(cts!=null)cts.Cancel();};ping=PlayerUi.Text("Ping — нет измерений",18,true);stability=PlayerUi.Text("Стабильность станет известна после измерения");problem=PlayerUi.Text("",10,false,Theme.Muted);card.Add(ping);card.Add(stability);card.Add(problem);Add(card);
   var traffic=new PlayerCard();traffic.Add(PlayerUi.Text("Фоновые загрузки",18,true));traffic.Add(PlayerUi.Text("Ограничьте исходящую скорость выбранной программы. На скорость скачивания это ограничение не действует; все экземпляры выбранного EXE будут затронуты.",10,false,Theme.Muted));traffic.Add(executable);var choose=PlayerUi.Button("Выбрать программу");choose.Click+=delegate{using(var dialog=new OpenFileDialog {Filter="Программа (*.exe)|*.exe"})if(dialog.ShowDialog()==DialogResult.OK)executable.Text=dialog.FileName;};traffic.Add(choose);traffic.Add(PlayerUi.Text("Максимальная скорость отправки, Мбит/с",10));traffic.Add(speed);traffic.Add(limit);limitState=PlayerUi.Text("",10,false,Theme.Muted);traffic.Add(limitState);limit.CheckedChanged+=async delegate{if(render)return;try{bool requested=limit.Checked;render=true;limit.Checked=!requested;render=false;if(context.Preview)return;if(!PlayerUi.Confirm(this,requested?"Ограничить фоновый трафик?":"Восстановить ограничения?",requested?"Ограничить отправку выбранного EXE до "+speed.Value+" Мбит/с? Потребуется UAC. Системные процессы и античит запрещены.":"Снять все ограничения исходящей скорости, созданные OpenAntiLag? Потребуется UAC.",false))return;if(requested)await context.ApplyBackgroundLimit(executable.Text,(long)speed.Value*1000000);else{var module=context.Recovery()[3];await context.Optimizer.Module(module.Name,module.Restore,()=>!module.Pending());}}catch(Exception error){context.Notice=error.Message;context.Emit();}RefreshState();};var advanced=PlayerUi.Button("Расширенные настройки");advanced.Click+=delegate{expert(5,"Интернет · расширенные ограничения");};traffic.Add(advanced);var details=PlayerUi.Button("Подробная диагностика");details.Click+=delegate{expert(4,"Интернет · диагностика соединений");};traffic.Add(details);Add(traffic);
  }
  async Task Probe(){if(cts!=null)return;string target=NetworkInput.Host(host.Text);if(Context.Preview){Context.Notice="Предпросмотр: сетевые запросы отключены.";Context.Emit();return;}if(!PlayerUi.Confirm(this,"Проверить сеть?","В течение 30 секунд будут отправляться диагностические ICMP-пробы к "+target+" с интервалом 2 секунды. Другие адреса, игровые серверы и DNS этим тестом не опрашиваются.",false))return;cts=new CancellationTokenSource();start.Enabled=false;cancel.Enabled=true;host.Enabled=false;connection.Text="Проверяем выбранный узел…";try{await Context.Network.Run(new MonitorOptions {Host=target,DurationSeconds=30,IntervalMs=2000},cts.Token);connection.Text="Измерение завершено";}catch(OperationCanceledException){connection.Text="Измерение завершено по вашей команде";}finally{cts.Dispose();cts=null;start.Enabled=true;cancel.Enabled=false;host.Enabled=true;RefreshState();}}
  public override void RefreshState(){var all=Context.Network.History.Snapshot();var target=all.Where(s=>s.Kind=="ICMP").Select(s=>s.Target).LastOrDefault();var data=all.Where(s=>s.Kind=="ICMP"&&s.Target==target).ToArray();var summary=ProbeSummary.Calculate(data);if(summary.Received>0){ping.Text="Диагностический ping: "+summary.Current.Value.ToString("0")+" мс";stability.Text=summary.Jitter.HasValue?"Колебания задержки: "+summary.Jitter.Value.ToString("0.0")+" мс" :"Нужно несколько ответов для оценки стабильности";problem.Text=summary.Lost>0?"Без ответа: "+summary.Lost+" из "+summary.Sent+" диагностических проб. Узел может фильтровать ICMP — это не доказательство потери пакетов игры.":"В этом измерении все отправленные пробы получили ответ. Узел: "+target;}else if(data.Length>0){ping.Text="Узел не ответил на ICMP";problem.Text="Это может быть фильтрация ICMP. Проверьте другой разрешённый адрес или расширенную диагностику.";}render=true;try{int pending=Context.NetworkPendingQos();limit.CheckState=pending>0?CheckState.Indeterminate:CheckState.Unchecked;limit.Enabled=pending>=0&&!Context.Preview&&!Context.Optimizer.Status.Busy;limitState.Text=Context.NetworkStatus();}finally{render=false;}}
  protected override void Dispose(bool disposing){if(disposing&&cts!=null)cts.Cancel();base.Dispose(disposing);}
 }
 public sealed class ResultsPage:PlayerPage {
  readonly Label lastSession,cpu,ram,network,operations;readonly TextBox details=new TextBox {Multiline=true,ReadOnly=true,Height=160,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Surface,ForeColor=Theme.Muted,BorderStyle=BorderStyle.None,Visible=false};
  public ResultsPage(PlayerContext context,Action<int,string> expert):base(context,"Результаты","Показываем измерения и фактические действия. Применение настроек само по себе не доказывает улучшение."){Name="resultsPage";var grid=new CardGrid();var session=new PlayerCard();session.Add(PlayerUi.Text("Последняя игровая сессия",18,true));lastSession=PlayerUi.Text("Измерений игровой сессии пока нет");session.Add(lastSession);session.Add(PlayerUi.Text("Измерение FPS недоступно",18,true));session.Add(PlayerUi.Text("1% Low и frametime также недоступны: проверенный сборщик не подключён.",10,false,Theme.Muted));grid.Controls.Add(session);var measurements=new PlayerCard();measurements.Add(PlayerUi.Text("Измеренные показатели",18,true));cpu=PlayerUi.Text("CPU — нет данных");ram=PlayerUi.Text("Память — нет данных");network=PlayerUi.Text("Ping / стабильность — нет данных");measurements.Add(cpu);measurements.Add(ram);measurements.Add(network);var benchmark=PlayerUi.Button("Сравнение «до / после»");benchmark.Click+=delegate{expert(7,"Сопоставимые измерения CPU/RAM");};measurements.Add(benchmark);grid.Controls.Add(measurements);Add(grid);var activity=new PlayerCard();activity.Add(PlayerUi.Text("Что выполнила программа",18,true));operations=PlayerUi.Text("Операций пока нет");activity.Add(operations);var show=PlayerUi.Button("Подробности операций");show.Click+=delegate{details.Visible=!details.Visible;};activity.Add(show);activity.Add(details);Add(activity);details.HandleCreated+=delegate{WindowTheme.Scrollbar(details.Handle);};}
  public override void RefreshState(){lastSession.Text=Context.Session.LastStartUtc.HasValue?"Запуск: "+Context.Session.LastStartUtc.Value.ToLocalTime().ToString("g")+(Context.Session.LastEndUtc.HasValue?"\nЗавершение: "+Context.Session.LastEndUtc.Value.ToLocalTime().ToString("g"):"\nИгра запущена"):"Сессии в этом запуске приложения ещё не измерялись.";var sample=Context.Measurements.Last;if(sample!=null){cpu.Text="CPU компьютера: "+(sample.CpuPercent.HasValue?sample.CpuPercent.Value.ToString("0.0")+"%":"недоступно")+" · CPU процесса: "+(sample.ProcessCpuPercent.HasValue?sample.ProcessCpuPercent.Value.ToString("0.0")+"%":"недоступно");ram.Text="Последнее измерение · PID "+sample.ProcessId+" · память процесса "+(sample.ProcessWorkingSet.HasValue?(sample.ProcessWorkingSet.Value/1024/1024)+" МБ":"недоступна")+"\nСвободно RAM: "+(sample.RamAvailable/1024/1024)+" МБ";}var samples=Context.Network.History.Snapshot().Where(s=>s.Kind=="ICMP").ToArray();if(samples.Length>0){string target=samples.Last().Target;var summary=ProbeSummary.Calculate(samples.Where(s=>s.Target==target));network.Text="Диагностический узел: "+target+"\nСредний ping: "+(summary.Mean.HasValue?summary.Mean.Value.ToString("0.0")+" мс":"нет ответа")+" · колебания: "+(summary.Jitter.HasValue?summary.Jitter.Value.ToString("0.0")+" мс":"недостаточно данных");}var records=Context.Optimizer.Operations().Reverse().Take(8).ToArray();operations.Text=records.Length==0?(Context.Selected!=null&&!String.IsNullOrEmpty(Context.Selected.LastResult)?Context.Selected.LastResult:"После запуска программы операций ещё не было."):String.Join("\n\n",records.Select(r=>(r.Success?"✓ ":"! ")+r.Name+" · "+r.Utc.ToLocalTime().ToString("HH:mm")+" · "+(r.Success?"подтверждено":"требует внимания")));details.Text=String.Join("\r\n\r\n",records.Select(r=>r.Name+": "+r.Result));}
 }
 public sealed class SettingsPage:PlayerPage {
  public SettingsPage(PlayerContext context,Action<int,string> expert,Action<string> navigate,Action wizard):base(context,"Настройки","Дополнительные инструменты, защита и единое восстановление."){Name="settingsPage";var general=new PlayerCard();general.Add(PlayerUi.Text("Приложение",18,true));var updates=new CheckBox {Text="Проверять обновления автоматически",AutoSize=true,Checked=context.Preview||Updates.Enabled};updates.CheckedChanged+=delegate{if(!context.Preview)Updates.Enabled=updates.Checked;};general.Add(updates);var startup=new CheckBox {Text="Запускать с Windows",AutoSize=true,Checked=!context.Preview&&Startup.Enabled};startup.CheckedChanged+=delegate{try{if(!context.Preview)Startup.Enabled=startup.Checked;}catch(Exception error){context.Notice=error.Message;context.Emit();}};general.Add(startup);general.Add(PlayerUi.Text("Нет обязательного аккаунта и телеметрии. Ключ NextDNS хранится локально с защитой Windows.",10,false,Theme.Muted));var setup=PlayerUi.Button("Мастер настройки");setup.Click+=delegate{wizard();};general.Add(setup);var recover=PlayerUi.Button("Восстановить настройки","openRecovery");recover.Click+=delegate{navigate("Recovery");};general.Add(recover);Add(general);var privacy=new PlayerCard();privacy.Add(PlayerUi.Text("DNS и защита",18,true));privacy.Add(PlayerUi.Text("Выбор DNS и необязательное управление вашим NextDNS. Обычная смена DNS не включает шифрование.",10,false,Theme.Muted));var dns=PlayerUi.Button("DNS и защита");dns.Click+=delegate{expert(6,"Настройки · DNS и защита");};privacy.Add(dns);Add(privacy);var advanced=new PlayerCard();advanced.Add(PlayerUi.Text("Дополнительно",18,true));advanced.Add(PlayerUi.Text("Точные параметры Windows, видеокарты и профессиональные сетевые инструменты. Некоторые действия глобальные, требуют UAC или перезагрузки.",10,false,Theme.Muted));foreach(var item in new[]{new {Index=0,Name="Система и питание"},new {Index=1,Name="NVIDIA"},new {Index=2,Name="AMD"},new {Index=3,Name="Шейдеры"},new {Index=4,Name="Диагностика сети"},new {Index=5,Name="Ограничения интернета"},new {Index=7,Name="Измерения и экспорт"}}){var entry=item;var button=PlayerUi.Button(entry.Name);button.Click+=delegate{expert(entry.Index,"Дополнительно · "+entry.Name);};advanced.Add(button);}Add(advanced);}
 }
 public sealed class RecoveryPage:PlayerPage {
  readonly Label outcome;readonly RecoveryModule[] modules;
  public RecoveryPage(PlayerContext context):base(context,"Восстановление настроек","Модули используют свои сохранённые копии. Не удаляйте журналы, чтобы снять предупреждение."){Name="recoveryPage";modules=context.Recovery();var intro=new PlayerCard();intro.Add(PlayerUi.Text("Вернуть изменения приложения",18,true));intro.Add(PlayerUi.Text("Проверьте все затронутые разделы. Может потребоваться несколько запросов UAC. Подготовленные шейдеры и списки NextDNS автоматически не откатываются.",10,false,Theme.Muted));var all=PlayerUi.Button("Восстановить все модули","restoreAllModules",true);all.Enabled=!context.Preview;PlayerUi.Action(all,async()=>{if(PlayerUi.Confirm(this,"Восстановление","Восстановить сохранённые параметры Windows, видеокарты, ограничения трафика и DNS? Внешние изменения сохраняются. Для системных и сетевых параметров может потребоваться UAC.",context.Preview)){context.Session.SuppressCurrentRun(context.Selected,context.Processes);await context.Optimizer.RestoreAll(modules);}},context);intro.Add(all);outcome=PlayerUi.Text("Каждый модуль подтвердит результат отдельно.");intro.Add(outcome);Add(intro);var grid=new CardGrid();foreach(var module in modules){var selected=module;var card=new PlayerCard();card.Add(PlayerUi.Text(selected.Name,16,true));card.Add(PlayerUi.Text("Восстанавливаются только записи из сохранённого журнала этого модуля.",10,false,Theme.Muted));var button=PlayerUi.Button("Восстановить","restore_"+selected.Name);button.Enabled=!context.Preview;PlayerUi.Action(button,async()=>{if(PlayerUi.Confirm(this,"Восстановить "+selected.Name,"Проверить и восстановить сохранённые изменения модуля «"+selected.Name+"»?",context.Preview)){if(selected.Name=="Профиль Windows")context.Session.SuppressCurrentRun(context.Selected,context.Processes);await context.Optimizer.Module(selected.Name,selected.Restore,()=>!selected.Pending());}},context);card.Add(button);grid.Controls.Add(card);}Add(grid);}
  public override void RefreshState(){outcome.Text=Context.Optimizer.Status.Message;}
 }
}
